theorem pSubgroup_le_sylow {G : Type*} [Group G] {p : ℕ}
    {H : Subgroup G} (hH : IsPrimePowerGroup p H) :
    ∃ P : SylowSubgroup p G, H ≤ P.1

theorem sylow_conjugate {G : Type*} [Group G] {p : ℕ}
    [Fact p.Prime] [Finite (SylowSubgroup p G)] (P Q : SylowSubgroup p G) :
    ∃ g : G, P.1.map (MulAut.conj g).toMonoidHom = Q.1

theorem sylow_number_dvd_index {G : Type*} [Group G] {p : ℕ}
    [Fact p.Prime] [Finite (SylowSubgroup p G)] (P : SylowSubgroup p G) :
    Nat.card (SylowSubgroup p G) ∣ P.1.index

theorem sylow_unique_of_normal {G : Type*} [Group G] {p : ℕ}
    [Fact p.Prime] [Finite (SylowSubgroup p G)] (P : SylowSubgroup p G) (hP : P.1.Normal) :
    ∀ Q : SylowSubgroup p G, Q = P

theorem generator_order_eq_group_card {G : Type*} [Group G] {g : G}
    (hg : cyclicSubgroup g = ⊤) :
    orderOf g = Nat.card G

theorem idealCongruent_add {R : Type*} [Ring R] {I : Set R}
    (hI : TwoSidedIdealSet I) {a a' b b' : R}
    (ha : idealCongruent I a a') (hb : idealCongruent I b b') :
    idealCongruent I (a + b) (a' + b')

theorem idealCongruent_mul {R : Type*} [Ring R] {I : Set R}
    (hI : TwoSidedIdealSet I) {a a' b b' : R}
    (ha : idealCongruent I a a') (hb : idealCongruent I b b') :
    idealCongruent I (a * b) (a' * b')

theorem idealCongruent_neg {R : Type*} [Ring R] {I : Set R}
    (hI : TwoSidedIdealSet I) {a b : R} (hab : idealCongruent I a b) :
    idealCongruent I (-a) (-b)

theorem quotientRingProjection_eq_iff {R : Type*} [Ring R] {I : Set R}
    (hI : TwoSidedIdealSet I) (x y : R) :
    quotientRingProjection I hI x = quotientRingProjection I hI y ↔ idealCongruent I x y

theorem idealSetIntersection_is_ideal {R : Type*} [Ring R] {I J : Set R}
    (hI : TwoSidedIdealSet I) (hJ : TwoSidedIdealSet J) :
    TwoSidedIdealSet (I ∩ J)

theorem quotientRingProjection_eq_zero_iff {R : Type*} [CommRing R] {I : Set R}
    (hI : TwoSidedIdealSet I) (x : R) :
    quotientRingProjection I hI x = 0 ↔ x ∈ I

theorem quotientRingSet_mul_eq_zero_iff {R : Type*} [CommRing R] {I : Set R}
    (hI : TwoSidedIdealSet I) (a b : R) :
    quotientRingProjection I hI a * quotientRingProjection I hI b = 0 ↔ a * b ∈ I

theorem quotientRingSet_zero_ne_one_iff {R : Type*} [CommRing R] {I : Set R}
    (hI : TwoSidedIdealSet I) :
    (0 : quotientRingSet I hI) ≠ 1 ↔ I ≠ Set.univ

theorem directionalDerivative_eq_inner_gradient {f : H → ℝ} {x grad v : H}
    (h : HasGradientAt f grad x) :
    DirectionalDerivative f x v = inner ℝ grad v

theorem gradient_totalDerivative {f : H → ℝ} {x grad : H}
    (h : HasGradientAt f grad x) :
    HasFDerivAt f (InnerProductSpace.toDual ℝ H grad) x

theorem hessian_symmetric {n : ℕ} {f : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hf : ContDiffAt ℝ 2 f x) :
    SandronesLibrary.LinearAlgebra.Matrix.IsSymmetric (hessian f x)

theorem jacobian_apply {n m : ℕ} {f : (Fin n → ℝ) → (Fin m → ℝ)}
    {x : Fin n → ℝ} {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)}
    (h : HasFDerivAt f A x) (i : Fin m) (j : Fin n) :
    jacobian f x i j = A (Pi.single j 1) i

theorem jacobian_chain {n m p : ℕ}
    {f : (Fin n → ℝ) → (Fin m → ℝ)} {g : (Fin m → ℝ) → (Fin p → ℝ)}
    {x : Fin n → ℝ}
    {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)}
    {B : (Fin m → ℝ) →L[ℝ] (Fin p → ℝ)}
    (hf : HasFDerivAt f A x) (hg : HasFDerivAt g B (f x)) :
    jacobian (g ∘ f) x = jacobian g (f x) * jacobian f x

theorem multivariable_taylor_first_order {E F : Type*}
    [NormedAddCommGroup E] [NormedSpace ℝ E]
    [NormedAddCommGroup F] [NormedSpace ℝ F] [CompleteSpace F]
    {f : E → F} {x y : E}
    (hf : ∀ t ∈ Set.Icc (0 : ℝ) 1, ContDiffAt ℝ 1 f (x + t • y)) :
    f (x + y) = f x + ∫ t in (0 : ℝ)..1, fderiv ℝ f (x + t • y) y

theorem partialDerivative_eq {n m : ℕ} {f : (Fin n → ℝ) → (Fin m → ℝ)}
    {x : Fin n → ℝ} {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)}
    (h : HasFDerivAt f A x) (j : Fin n) :
    partialDerivative f x j = A (Pi.single j 1)

theorem totalDerivative_apply_eq_jacobian_mulVec {n m : ℕ}
    {f : (Fin n → ℝ) → (Fin m → ℝ)} {x v : Fin n → ℝ}
    {A : (Fin n → ℝ) →L[ℝ] (Fin m → ℝ)} (h : HasFDerivAt f A x) :
    A v = jacobian f x *ᵥ v

theorem totalDerivative_chain {f : E → F} {g : F → G}
    {x : E} {A : E →L[ℝ] F} {B : F →L[ℝ] G}
    (hf : HasFDerivAt f A x) (hg : HasFDerivAt g B (f x)) :
    HasFDerivAt (g ∘ f) (B.comp A) x

theorem continuousOn_integrableOn_closedRectangle {f : ℝ × ℝ → ℝ} {a b c d : ℝ}
    (hf : ContinuousOn f (closedRectangle a b c d)) :
    IntegrableOn f (closedRectangle a b c d) (volume.prod volume)

theorem IsJordanMeasurable.setIntegral_closure {n : ℕ} {s : Set (JordanEuc n)}
    (hs : IsJordanMeasurable s) (f : JordanEuc n → ℝ) :
    ∫ x in _root_.closure s, f x = ∫ x in s, f x

theorem HasRiemannBoxIntegral.integral_eq {n : ℕ} {f : (Fin n → ℝ) → ℝ}
    {I : RiemannBox n} {y : ℝ} (h : HasRiemannBoxIntegral f I y) :
    riemannBoxIntegral f I = y

theorem continuousOn_riemannIntegrableOnBox {n : ℕ} {f : (Fin n → ℝ) → ℝ}
    {I : RiemannBox n} (hf : ContinuousOn f (Box.Icc I)) :
