theorem riemannBoxIntegral_eq_setIntegral {n : ℕ} {f : (Fin n → ℝ) → ℝ}
    {I : RiemannBox n} (hf : ContinuousOn f (Box.Icc I)) :
    riemannBoxIntegral f I = ∫ x in (I : Set (Fin n → ℝ)), f x

lemma jordan_indicator_ae_continuous {n : ℕ} {s : Set (JordanEuc n)}
    {f : JordanEuc n → ℝ} (hs : IsJordanMeasurable s) (hf : Continuous f) :
    ∀ᵐ x ∂volume, ContinuousAt (s.indicator f) x

lemma jordan_indicator_bounded_on_box {n : ℕ} {s : Set (JordanEuc n)}
    {f : JordanEuc n → ℝ} (hf : Continuous f) (I : RiemannBox n) :
    ∃ C : ℝ, ∀ x ∈ Box.Icc I, ‖s.indicator f x‖ ≤ C

lemma continuousAt_comp {f : ℝ → ℝ} {g : ℝ → ℝ} {x : ℝ}
    (hg : ContinuousAt g (f x)) (hf : ContinuousAt f x) :
    ContinuousAt (fun y => g (f y)) x

theorem continuousOn_compact_uniformContinuousOn {X : Type} [MetricSpace X] {s : Set X} {f : X → ℝ}
    (hs : IsCompact s) (hsne : s.Nonempty) (hf : ContinuousOn f s) :
    UniformContinuousOn f s

theorem cover_theorem {X : Type} [MetricSpace X] {s : Set X} {f : X → ℝ} {ε : ℝ}
    (hpt : ∀ x ∈ s, ∃ δx > 0, ∀ y ∈ s, dist y x < δx → |f y - f x| < ε / 2) :
    s ⊆ ⋃ x : s, Metric.ball x.1 ((hpt x.1 x.2).choose / 2)

theorem hpt_theorem {X : Type} [MetricSpace X] {s : Set X} {f : X → ℝ}
    (hf : ContinuousOn f s) {ε : ℝ} (hε : 0 < ε) :
    ∀ x ∈ s, ∃ δx > 0, ∀ y ∈ s, dist y x < δx → |f y - f x| < ε / 2

lemma fin_strict_mono_le {n i j : ℕ} {x : ℕ → ℝ}
    (hx : ∀ k, k < n → x k < x (k+1)) (hij : i + 1 ≤ j) (hj : j < n) :
    x (i+1) ≤ x j

lemma mono_x_le {n m j : ℕ} {x : ℕ → ℝ}
    (hx : ∀ k, k < n → x k < x (k+1)) (hmj : m ≤ j) (hj : j < n) :
    x m ≤ x j

lemma mono_x_le_le {n m j : ℕ} {x : ℕ → ℝ}
    (hx : ∀ k, k < n → x k < x (k+1)) (hmj : m ≤ j) (hj : j ≤ n) :
    x m ≤ x j

lemma partition_disjoint {n i j : ℕ} {x : ℕ → ℝ} {t : ℝ}
    (hx : ∀ k, k < n → x k < x (k+1)) (hi : i < n) (hj : j < n) (hij : i ≠ j)
    (hti : t ∈ Set.Ioc (x i) (x (i+1))) : t ∉ Set.Ioc (x j) (x (j+1))

theorem boundedOn_ae_continuousOn_riemannIntegrableWithBound {f : ℝ → ℝ} {a b : ℝ}
    (hab : a ≤ b) (hb : BoundedOn f (Set.Icc a b))
    (hc : AlmostEverywhereContinuousOn f a b) : RiemannIntegrableWithBound f a b

theorem boundedOn_image_isBounded {f : ℝ → ℝ} {a b : ℝ}
    (hab : a ≤ b) (hb : BoundedOn f (Set.Icc a b)) :
