theorem oscillationWithin_lt_top_of_boundedOn {f : ℝ → ℝ} {a b x : ℝ}
    (hab : a ≤ b) (hx : x ∈ Set.Icc a b) (hb : BoundedOn f (Set.Icc a b)) :
    oscillationWithin f (Set.Icc a b) x < ⊤

theorem riemannIntegrableWithBound_ae_continuousOn {f : ℝ → ℝ} {a b : ℝ}
    (hab : a ≤ b) (h : RiemannIntegrableWithBound f a b) :
    AlmostEverywhereContinuousOn f a b

theorem hasDerivAt_riemannIntegral_right {a x : ℝ} {f : ℝ → ℝ}
    (hax : a < x) (hf : Continuous f) :
    HasDerivAt (fun u => riemannIntegral f a u) (f x) x

theorem riemannIntegral_eq_interval_of_riemannIntegrableWithBound {f : ℝ → ℝ} {a b : ℝ}
    (hab : a < b) (h : RiemannIntegrableWithBound f a b) :
    riemannIntegral f a b = ∫ x in Set.Ioc a b, f x ∂volume

theorem measurableSet_xNormalDomain {a b : ℝ} {lower upper : ℝ → ℝ}
    (hlower : Continuous lower) (hupper : Continuous upper) :
    MeasurableSet (xNormalDomain a b lower upper)

theorem measurableSet_xNormalDomain_of_measurable {a b : ℝ} {lower upper : ℝ → ℝ}
    (hlower : Measurable lower) (hupper : Measurable upper) :
    MeasurableSet (xNormalDomain a b lower upper)

theorem measurableSet_yNormalDomain_of_measurable {c d : ℝ} {left right : ℝ → ℝ}
    (hleft : Measurable left) (hright : Measurable right) :
    MeasurableSet (yNormalDomain c d left right)

theorem integrableOn_image_iff_integrableOn_absJacobian_mul {n : ℕ}
    {s : Set (JordanEuc n)} {φ : JordanEuc n → JordanEuc n}
    (hs : MeasurableSet s) (hφ : DifferentiableOn ℝ φ s) (hinj : InjOn φ s)
    (g : JordanEuc n → ℝ) :
    IntegrableOn g (φ '' s) ↔
      IntegrableOn (fun x ↦ absJacobianWithin φ s x * g (φ x)) s

theorem integral_image_eq_integral_absJacobian_mul {n : ℕ}
    {s : Set (JordanEuc n)} {φ : JordanEuc n → JordanEuc n}
    (hs : MeasurableSet s) (hφ : DifferentiableOn ℝ φ s) (hinj : InjOn φ s)
    (g : JordanEuc n → ℝ) :
    (∫ y in φ '' s, g y) =
      ∫ x in s, absJacobianWithin φ s x * g (φ x)

theorem volume_image_eq_lintegral_absJacobian {n : ℕ}
    {s : Set (JordanEuc n)} {φ : JordanEuc n → JordanEuc n}
    (hs : MeasurableSet s) (hφ : DifferentiableOn ℝ φ s) (hinj : InjOn φ s) :
    volume (φ '' s) = ∫⁻ x in s, ENNReal.ofReal (absJacobianWithin φ s x)

theorem accumulation_point_of_infinite_bounded {s : Set ℝ}
    (hs : s.Infinite) (hb : BddAbove s) (hbdl : BddBelow s) :
    ∃ x : ℝ, AccPt x (𝓟 s)

theorem nested_intervals_nonempty {a b : ℕ → ℝ}
    (hmono_A : Monotone a) (hanti_B : Antitone b) (hle : ∀ n, a n ≤ b n) :
    ∃ x : ℝ, ∀ n, x ∈ Set.Icc (a n) (b n)

lemma deriv_add_sub_real {f g : ℝ → ℝ} {x : ℝ}
    (hf : DifferentiableAt ℝ f x) (hg : DifferentiableAt ℝ g x) :
    deriv (f + g) x = deriv f x + deriv g x

lemma deriv_chain_rule_real {f : ℝ → ℝ} {g : ℝ → ℝ} {x : ℝ}
    (hf : DifferentiableAt ℝ f x) (hg : DifferentiableAt ℝ g (f x)) :
  deriv (fun y => g (f y)) x = deriv g (f x) * deriv f x

lemma deriv_mul_real {f g : ℝ → ℝ} {x : ℝ}
    (hf : DifferentiableAt ℝ f x) (hg : DifferentiableAt ℝ g x) :
    deriv (f * g) x = deriv f x * g x + f x * deriv g x

theorem alternatingForm_eq_zero_of_repeat {V : Type v} [AddCommGroup V] [LinearSpace K V]
    {k : ℕ} (ω : AlternatingForm K V k) (v : Fin k → V) {i j : Fin k}
    (hij : i ≠ j) (hrepeat : v i = v j) : ω v = 0

theorem dim_exteriorPower_eq_choose {V : Type v}
    [AddCommGroup V] [LinearSpace K V] [IsFiniteDimensional K V] (k : ℕ) :
    dim K (ExteriorPowerSpace K V k) = Nat.choose (dim K V) k

theorem dim_tensor_eq_mul {V : Type v} {W : Type w}
    [AddCommGroup V] [LinearSpace K V] [AddCommGroup W] [LinearSpace K W] :
    dim K (TensorSpace K V W) = dim K V * dim K W

@[simp] theorem doubleDualEvaluation_apply {V : Type v}
    [AddCommGroup V] [LinearSpace K V] (v : V) (φ : DualSpace K V) :
    doubleDualEvaluation K v φ = φ v

theorem doubleDualEvaluation_bijective {V : Type v}
    [AddCommGroup V] [LinearSpace K V] [IsFiniteDimensional K V] :
    Function.Bijective (doubleDualEvaluation K (V := V))

@[simp] theorem dualTensorContraction_pureTensor {V : Type v}
    [AddCommGroup V] [LinearSpace K V] (φ : DualSpace K V) (v : V) :
    dualTensorContraction K (pureTensor K φ v) = φ v

@[simp] theorem pureTensor_smul_left {V : Type v} {W : Type w}
    [AddCommGroup V] [LinearSpace K V] [AddCommGroup W] [LinearSpace K W]
    (a : K) (v : V) (w : W) : pureTensor K (a • v) w = a • pureTensor K v w

@[simp] theorem pureTensor_smul_right {V : Type v} {W : Type w}
    [AddCommGroup V] [LinearSpace K V] [AddCommGroup W] [LinearSpace K W]
    (a : K) (v : V) (w : W) : pureTensor K v (a • w) = a • pureTensor K v w

theorem algebraicFormWedge_zero_left {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (η : AlgebraicDifferentialForm E l) :
    algebraicFormWedge (0 : AlgebraicDifferentialForm E k) η = 0

theorem algebraicFormWedge_zero_right {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (ω : AlgebraicDifferentialForm E k) :
    algebraicFormWedge ω (0 : AlgebraicDifferentialForm E l) = 0

theorem alternatingWedge_add_left {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (a₁ a₂ : E [⋀^Fin k]→ₗ[ℝ] ℝ) (b : E [⋀^Fin l]→ₗ[ℝ] ℝ) :
    alternatingWedge (a₁ + a₂) b = alternatingWedge a₁ b + alternatingWedge a₂ b

theorem alternatingWedge_add_right {E : Type u} [AddCommGroup E] [Module ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→ₗ[ℝ] ℝ) (b₁ b₂ : E [⋀^Fin l]→ₗ[ℝ] ℝ) :
    alternatingWedge a (b₁ + b₂) = alternatingWedge a b₁ + alternatingWedge a b₂

theorem continuousAlternatingWedge_add_left {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a₁ a₂ : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge (a₁ + a₂) b =
      continuousAlternatingWedge a₁ b + continuousAlternatingWedge a₂ b

theorem continuousAlternatingWedge_add_right {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b₁ b₂ : E [⋀^Fin l]→L[ℝ] ℝ) :
    continuousAlternatingWedge a (b₁ + b₂) =
      continuousAlternatingWedge a b₁ + continuousAlternatingWedge a b₂

theorem continuousAlternatingWedge_apply {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) (v : Fin (k + l) → E) :
    continuousAlternatingWedge a b v =
      alternatingWedge a.toAlternatingMap b.toAlternatingMap v

theorem continuousAlternatingWedge_norm_le {E : Type u}
    [NormedAddCommGroup E] [NormedSpace ℝ E] {k l : ℕ}
    (a : E [⋀^Fin k]→L[ℝ] ℝ) (b : E [⋀^Fin l]→L[ℝ] ℝ) :
