    {ancestors : List (List Hydra)} {grandparentSiblings parentSiblings : List Hydra}
    {before after : Hydra}
    (cut : RightmostSpineReplicatedCut stage ancestors grandparentSiblings
      parentSiblings before after) :
    Hydra.Step stage before after

theorem certifiedTransitivePredecessor_to_transGen {after before : Hydra}
    (steps : CertifiedTransitivePredecessor after before) :
    Relation.TransGen CertifiedPredecessor after before

theorem primrec_boundedProd {n : ℕ} {b : List.Vector ℕ n → ℕ}
    {f : List.Vector ℕ (n + 1) → ℕ}
    (hb : @Nat.Primrec' n b) (hf : @Nat.Primrec' (n + 1) f) :
    @Nat.Primrec' n (fun v => Finset.prod (Finset.range (b v)) (fun i => f (i ::ᵥ v)))

theorem primrec_boundedSum {n : ℕ} {b : List.Vector ℕ n → ℕ}
    {f : List.Vector ℕ (n + 1) → ℕ}
    (hb : @Nat.Primrec' n b) (hf : @Nat.Primrec' (n + 1) f) :
    @Nat.Primrec' n (fun v => Finset.sum (Finset.range (b v)) (fun i => f (i ::ᵥ v)))

theorem primrec_iterated {n : ℕ} {base : List.Vector ℕ n → ℕ}
    {step : List.Vector ℕ (n + 1) → ℕ} {count : List.Vector ℕ n → ℕ}
    (hbase : @Nat.Primrec' n base) (hstep : @Nat.Primrec' (n + 1) step)
    (hcount : @Nat.Primrec' n count) :
    @Nat.Primrec' n (fun v => Nat.rec (base v) (fun _ IH => step (IH ::ᵥ v)) (count v))

theorem primrec_primitiveRecursion {z : ℕ} {step : ℕ → ℕ → ℕ}
    (hstep : @Nat.Primrec' 2 (fun v : List.Vector ℕ 2 => step v.head v.tail.head)) :
    @Nat.Primrec' 1 (fun v : List.Vector ℕ 1 => primitiveRecursion z step v.head)

theorem densityMean_eq_integral_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ}
    {s : ℝ → 𝓧 → ℝ} (h : IsRegularDominatedFamily ν p s) (T : 𝓧 → ℝ) (θ : ℝ) :
    densityMean ν p T θ = ∫ x, T x ∂(modelMeasure ν p θ)

theorem fisherInformation_eq_integral_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ}
    {s : ℝ → 𝓧 → ℝ} (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    fisherInformation ν p s θ = ∫ x, (s θ x) ^ 2 ∂(modelMeasure ν p θ)

theorem fisherInformation_nonneg {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ} {s : ℝ → 𝓧 → ℝ}
    (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    0 ≤ fisherInformation ν p s θ

theorem integral_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ} {s : ℝ → 𝓧 → ℝ}
    (h : IsRegularDominatedFamily ν p s) (θ : ℝ) (F : 𝓧 → ℝ) :
    ∫ x, F x ∂(modelMeasure ν p θ) = ∫ x, F x * p θ x ∂ν

theorem isProbabilityMeasure_modelMeasure {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ}
    {s : ℝ → 𝓧 → ℝ} (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    IsProbabilityMeasure (modelMeasure ν p θ)

theorem modelMeasure_apply (ν : Measure 𝓧) (p : ℝ → 𝓧 → ℝ) (θ : ℝ) {s : Set 𝓧}
    (hs : MeasurableSet s) :
    modelMeasure ν p θ s = ∫⁻ x in s, ENNReal.ofReal (p θ x) ∂ν

theorem score_integral_eq_zero {ν : Measure 𝓧} {p : ℝ → 𝓧 → ℝ} {s : ℝ → 𝓧 → ℝ}
    (h : IsRegularDominatedFamily ν p s) (θ : ℝ) :
    ∫ x, s θ x * p θ x ∂ν = 0

theorem sq_integral_mul_le_integral_sq_mul_integral_sq {μ : Measure 𝓧} {f g : 𝓧 → ℝ}
    (hf : MemLp f 2 μ) (hg : MemLp g 2 μ) :
    (∫ x, f x * g x ∂μ) ^ 2 ≤ (∫ x, (f x) ^ 2 ∂μ) * (∫ x, (g x) ^ 2 ∂μ)

theorem compact_elim_finite_subcover {X : Type*} [TopologicalSpace X] {s : Set X}
    (hs : IsCompact s) {ι : Type*} (U : ι → Set X) (hUo : ∀ i : ι, IsOpen (U i))
    (hsU : s ⊆ ⋃ i, U i) : ∃ t : Finset ι, s ⊆ ⋃ i ∈ t, U i

theorem tychonoff {ι : Type*} {X : ι → Type*} [∀ i, TopologicalSpace (X i)]
    {s : ∀ i, Set (X i)} (hs : ∀ i, IsCompact (s i)) :
    IsCompact { x : ∀ i, X i | ∀ i, x i ∈ s i }

theorem chartInvDiscrete_chartToDiscrete [PathConnectedSpace X] {y : X}
    (U : SmallNeighborhood y) (q : ProjectionPreimage H U.carrier) :
    chartInvDiscrete H U (chartToDiscrete H U q) = q

theorem chartTransition_fst [PathConnectedSpace X] {y z : X}
    (U : SmallNeighborhood y) (V : SmallNeighborhood z) (q : ChartOverlap H U V) :
    (chartTransition H U V q).1 = (⟨q.1.1, q.1.2.2⟩ : V.carrier)

theorem continuous_chartTransition_fst [PathConnectedSpace X] {y z : X}
    (U : SmallNeighborhood y) (V : SmallNeighborhood z) :
    Continuous (fun q : ChartOverlap H U V => (chartTransition H U V q).1)

theorem IsPathConnected.image {Y : Type*} {τX : TextbookTopology X}
    {τY : TextbookTopology Y} {s : Set X} {f : X → Y} (hs : IsPathConnected τX s)
    (hf : Continuous τX τY f) : IsPathConnected τY (f '' s)

theorem Joined.map {Y : Type*} {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {a b : X} {f : X → Y} (h : Joined τX a b) (hf : Continuous τX τY f) :
    Joined τY (f a) (f b)

theorem image_pathComponent_subset {Y : Type*} {τY : TextbookTopology Y} {f : X → Y}
    (hf : Continuous tau τY f) (a : X) :
    f '' pathComponent tau a ⊆ pathComponent τY (f a)

theorem pathComponent_eq_of_mem_inter {a b : X}
    (h : (pathComponent tau a ∩ pathComponent tau b).Nonempty) :
    pathComponent tau a = pathComponent tau b

theorem isPathConnected_image [TopologicalSpace X] [TopologicalSpace Y]
    {s : Set X} (hs : _root_.IsPathConnected s) {f : X → Y}
    (hf : _root_.Continuous f) : _root_.IsPathConnected (f '' s)

@[ext]
theorem ext {τX : TextbookTopology X} {τY : TextbookTopology Y} {f g : X → Y}
    {F G : Homotopy τX τY f g} (h : ∀ p, F p = G p) : F = G

@[simp] theorem refl_apply {τX : TextbookTopology X} {τY : TextbookTopology Y}
    {f : X → Y} (hf : Continuous τX τY f) (p : X × UnitInterval) :
    refl hf p = f p.1

@[simp]
theorem isOpen_toMathlib (τ : TextbookTopology X) (s : Set X) :
    @_root_.IsOpen X τ.toMathlib s ↔ τ.IsOpen s

@[simp]
theorem fromMathlib_toMathlib {τX : TextbookTopology X} {τY : TextbookTopology Y}
    (e : Homeomorphism τX τY) : fromMathlib (toMathlib e) = e

theorem toMathlib_symm {τX : TextbookTopology X} {a b : X} (γ : Path τX a b) :
    toMathlib γ.symm =
      @_root_.Path.symm X τX.toMathlib a b (toMathlib γ)

theorem toMathlib_trans {τX : TextbookTopology X} {a b c : X}
    (γ : Path τX a b) (δ : Path τX b c) :
    toMathlib (γ.trans δ) =
      @_root_.Path.trans X τX.toMathlib a b c (toMathlib γ) (toMathlib δ)

@[simp]
theorem isClosed_toMathlib (τ : TextbookTopology X) (s : Set X) :
    @_root_.IsClosed X τ.toMathlib s ↔ τ.IsClosed s

theorem connectorChange_cast {x₀ z z' : X}
